describe('Alert Dialog Interaction Blocking', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should block interaction with page when alert dialog is open', () => {
    // Intercept the API call that triggers the alert dialog
    cy.intercept('GET', '/api/alert').as('getAlert');
    cy.get('[data-testid="trigger-alert-button"]').click();

    // Wait for the alert dialog to appear
    cy.wait('@getAlert');

    // Verify the alert dialog is visible
    cy.get('[data-testid="alert-dialog"]').should('be.visible');
    cy.get('[data-testid="alert-title"]').should('contain', 'Error');
    cy.get('[data-testid="alert-message"]').should('contain', 'Something went wrong');

    // Attempt to interact with the page
    cy.get('[data-testid="dashboard-table"]').should('be.visible');
    cy.get('[data-testid="dashboard-table"]').click();

    // Verify the click is blocked
    cy.get('[data-testid="dashboard-table"]').should('not.be.visible');
    cy.get('[data-testid="dashboard-table"]').should('not.have.class', 'active');

    // Verify the alert dialog is still visible
    cy.get('[data-testid="alert-dialog"]').should('be.visible');
  });

  it('should close the alert dialog and restore page interaction when dismiss button is clicked', () => {
    // Intercept the API call that triggers the alert dialog
    cy.intercept('GET', '/api/alert').as('getAlert');
    cy.get('[data-testid="trigger-alert-button"]').click();

    // Wait for the alert dialog to appear
    cy.wait('@getAlert');

    // Verify the alert dialog is visible
    cy.get('[data-testid="alert-dialog"]').should('be.visible');
    cy.get('[data-testid="alert-title"]').should('contain', 'Error');
    cy.get('[data-testid="alert-message"]').should('contain', 'Something went wrong');

    // Click the dismiss button
    cy.get('[data-testid="alert-dismiss-button"]').click();

    // Verify the alert dialog is no longer visible
    cy.get('[data-testid="alert-dialog"]').should('not.exist');

    // Verify page interaction is restored
    cy.get('[data-testid="dashboard-table"]').should('be.visible');
    cy.get('[data-testid="dashboard-table"]').click();
  });
});
